#include "stdlib/stats/base/ndarray/snanmaxabs.h"
#include "stdlib/ndarray/ctor.h"
#include <stdint.h>
#include <stdio.h>

int main( void ) {
	// Create an underlying data buffer:
	float x[] = { 1.0f, -2.0f, 0.0f / 0.0f, 2.0f, -3.0f, 0.0f / 0.0f, 4.0f };

	// Define ndarray meta data:
	int8_t ndims = 1;
	int64_t shape[] = { 7 };
	int64_t strides[] = { 1 };
	int64_t offset = 0;

	// Create an ndarray:
	struct ndarray *arr = stdlib_ndarray_allocate( 11 /* float32 */, (uint8_t *)(void *)x, ndims, shape, strides, offset, 1 /* row-major */, 0 /* strict */, 0, NULL );
	if ( arr == NULL ) {
		fprintf( stderr, "Error allocating ndarray.\n" );
		return 1;
	}

	// Create a list of ndarrays:
	const struct ndarray *arrays[] = { arr };

	// Compute the maximum absolute value:
	float v = stdlib_stats_snanmaxabs( arrays );

	// Print the result:
	printf( "maxabs: %f\n", v );

	// Free allocated memory:
	stdlib_ndarray_free( arr );

	return 0;
}
